"""Authentication: register, login, current user."""

from __future__ import annotations

import re
import sqlite3

from fastapi import APIRouter, Depends, Response, status
from pydantic import BaseModel

from app.config import Settings, get_settings
from app.db import get_db, utc_now
from app.errors import bad_request, conflict, unauthorized
from app.security import (
    create_access_token,
    get_current_user,
    hash_password,
    password_problem,
    verify_password,
)

router = APIRouter(prefix="/api/auth", tags=["auth"])

USERNAME_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}$")


class RegisterIn(BaseModel):
    username: str
    password: str


class RegisterOut(BaseModel):
    id: int
    username: str
    created_at: str


class LoginIn(BaseModel):
    username: str
    password: str


class LoginOut(BaseModel):
    access_token: str
    token_type: str = "bearer"
    expires_in: int


class MeOut(BaseModel):
    id: int
    username: str
    created_at: str


@router.post(
    "/register",
    response_model=RegisterOut,
    status_code=status.HTTP_201_CREATED,
    summary="Create a new account",
)
def register(
    data: RegisterIn,
    conn: sqlite3.Connection = Depends(get_db),
    settings: Settings = Depends(get_settings),
) -> RegisterOut:
    username = data.username.strip()
    password = data.password

    if not USERNAME_RE.fullmatch(username):
        raise bad_request("invalid_username", "Username must be 3-32 letters, digits, _ or -.")

    problem = password_problem(password)
    if problem:
        raise bad_request("weak_password", problem)

    password_hash = hash_password(password)
    now = utc_now()

    try:
        cur = conn.execute(
            "INSERT INTO users (username, password_hash, created_at) VALUES (?, ?, ?)",
            (username, password_hash, now),
        )
    except sqlite3.IntegrityError:
        raise conflict("username_taken", "This username is already taken.")

    user_id = cur.lastrowid
    return RegisterOut(id=user_id, username=username, created_at=now)


@router.post("/login", response_model=LoginOut, summary="Sign in and get an access token")
