import { apiFetch, ApiError } from "./api.js";
import { showMessage, formValues, whileBusy, el, clear, formatTime } from "./ui.js";

const TOKEN_KEY = "taskboard.token";

function loadToken() {
  return localStorage.getItem(TOKEN_KEY);
}

function clearToken() {
  localStorage.removeItem(TOKEN_KEY);
}

function isSignedIn() {
  return !!loadToken();
}

if (!isSignedIn()) {
  location.href = "login.html";
}

const userNameEl = document.getElementById("user-name");
const signOutBtn = document.getElementById("sign-out");
const listEl = document.getElementById("todo-list");
const formEl = document.getElementById("todo-form");
const titleInput = document.getElementById("todo-title");
const filterAll = document.getElementById("filter-all");
const filterOpen = document.getElementById("filter-open");
const filterDone = document.getElementById("filter-done");
const prevBtn = document.getElementById("prev-page");
const nextBtn = document.getElementById("next-page");
const pageInfo = document.getElementById("page-info");

let currentFilter = "all";
let currentOffset = 0;
const PAGE_SIZE = 20;

async function fetchMe() {
  try {
    const me = await apiFetch("/api/auth/me");
    userNameEl.textContent = me.username;
  } catch (err) {
    if (err instanceof ApiError && err.status === 401) {
      clearToken();
      location.href = "login.html";
    } else {
      showMessage("Failed to load user.", "error");
    }
  }
}

function getFilterParam() {
  if (currentFilter === "open") return "false";
  if (currentFilter === "done") return "true";
  return null;
}

async function loadTodos() {
  const done = getFilterParam();
  const query = new URLSearchParams({ limit: PAGE_SIZE, offset: currentOffset });
  if (done !== null) query.set("done", done);

  try {
    const data = await apiFetch(`/api/todos?${query.toString()}`);
    renderTodos(data.items);
    updatePager(data.total, data.limit, data.offset);
  } catch (err) {
    if (err instanceof ApiError && err.status === 401) {
      clearToken();
      location.href = "login.html";
    } else {
      showMessage("Failed to load todos.", "error");
    }
  }
}

function renderTodos(todos) {
  clear(listEl);
  if (todos.length === 0) {
    listEl.appendChild(el("li", { class: "list-item muted" }, "No todos yet."));
    return;
  }
  for (const todo of todos) {
    const li = el("li", { class: "list-item" + (todo.done ? " done" : "") }, [
      el("input", { type: "checkbox", checked: todo.done, "aria-label": "Mark as " + (todo.done ? "open" : "done") }),
      el("span", { class: "title grow" }, todo.title),
      el("button", { class: "rename", "aria-label": "Rename" }, "✏️"),
      el("button", { class: "danger delete", "aria-label": "Delete" }, "🗑️"),
    ]);
    li.dataset.id = todo.id;
    li.dataset.title = todo.title;
    li.dataset.done = todo.done;
    listEl.appendChild(li);
  }
}

function updatePager(total, limit, offset) {
  const currentPage = Math.floor(offset / limit) + 1;
  const totalPages = Math.ceil(total / limit) || 1;
  pageInfo.textContent = `Page ${currentPage} of ${totalPages}`;
  prevBtn.disabled = currentPage === 1;
  nextBtn.disabled = currentPage === totalPages;
}

async function createTodo(title) {
  try {
    await apiFetch("/api/todos", { method: "POST", body: { title } });
    await loadTodos();
  } catch (err) {
    if (err instanceof ApiError) showMessage(err.message, "error");
    else showMessage("Failed to create todo.", "error");
  }
}

async function updateTodo(id, patch) {
  try {
    await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: patch });
    await loadTodos();
  } catch (err) {
    if (err instanceof ApiError) showMessage(err.message, "error");
    else showMessage("Failed to update todo.", "error");
  }
}

async function deleteTodo(id) {
  try {
    await apiFetch(`/api/todos/${id}`, { method: "DELETE" });
    await loadTodos();
  } catch (err) {
    if (err instanceof ApiError) showMessage(err.message, "error");
    else showMessage("Failed to delete todo.", "error");
  }
}

formEl.addEventListener("submit", async (e) => {
  e.preventDefault();
  const title = titleInput.value.trim();
  if (!title) return;
  await whileBusy(formEl, () => createTodo(title));
  titleInput.value = "";
});

listEl.addEventListener("click", async (e) => {
  const li = e.target.closest(".list-item");
  if (!li) return;
  const id = Number(li.dataset.id);

  if (e.target.type === "checkbox") {
    const done = e.target.checked;
    await updateTodo(id, { done });
  } else if (e.target.classList.contains("rename")) {
    const currentTitle = li.dataset.title;
    const newTitle = prompt("Rename todo:", currentTitle);
    if (newTitle !== null && newTitle.trim() !== "" && newTitle.trim() !== currentTitle) {
      await updateTodo(id, { title: newTitle.trim() });
    }
  } else if (e.target.classList.contains("delete")) {
    if (confirm("Delete this todo?")) {
      await deleteTodo(id);
    }
  }
});

function setFilter(filter) {
  currentFilter = filter;
  currentOffset = 0;
  filterAll.classList.toggle("active", filter === "all");
  filterOpen.classList.toggle("active", filter === "open");
  filterDone.classList.toggle("active", filter === "done");
  loadTodos();
}

filterAll.addEventListener("click", () => setFilter("all"));
filterOpen.addEventListener("click", () => setFilter("open"));
filterDone.addEventListener("click", () => setFilter("done"));

prevBtn.addEventListener("click", () => {
  if (currentOffset >= PAGE_SIZE) {
    currentOffset -= PAGE_SIZE;
    loadTodos();
  }
});

nextBtn.addEventListener("click", () => {
  currentOffset += PAGE_SIZE;
  loadTodos();
});

signOutBtn.addEventListener("click", () => {
  clearToken();
  location.href = "login.html";
});

fetchMe();
loadTodos();
